CREATE OR REPLACE FUNCTION public.cerrar_solicitud_traslado(p_solicitud_id bigint, p_estado estado_traslado, p_usuario text DEFAULT NULL::text, p_nota text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare v_sol solicitud_traslado%rowtype;
begin
  if p_estado not in ('RECHAZADO','CANCELADO') then
    raise exception 'Solo se admite RECHAZADO o CANCELADO';
  end if;
  select * into v_sol from solicitud_traslado where id = p_solicitud_id for update;
  if not found then raise exception 'Solicitud % no existe', p_solicitud_id; end if;
  if v_sol.estado <> 'SOLICITADO' then
    raise exception 'Solo se puede cerrar una solicitud en estado SOLICITADO (está en %)', v_sol.estado;
  end if;
  update solicitud_traslado
     set estado = p_estado, nota = coalesce(p_nota, nota), despachado_por = p_usuario
   where id = p_solicitud_id;
  return jsonb_build_object('solicitud_id', p_solicitud_id, 'estado', p_estado);
end;
$function$
